  // Rule 3 — Overpopulation (live cell with > 3 neighbors dies)
  it.todo("live cell with 4 neighbors dies — center (1,1) of plus-in-square dies");

  // Pattern examples
  it.todo("blinker oscillates — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]");
  it.todo("block is a still life — [(0,0),(1,0),(0,1),(1,1)] unchanged");
}
);

